package com.agriconnect.logistics;import io.micrometer.core.instrument.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.util.*;import org.slf4j.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.web.servlet.HandlerMapping;@Component class ObservabilityFilter extends OncePerRequestFilter{private static final Logger log=LoggerFactory.getLogger(ObservabilityFilter.class);private final MeterRegistry metrics;ObservabilityFilter(MeterRegistry m){metrics=m;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{long start=System.nanoTime();String trace=r.getHeader("X-Trace-Id");if(trace==null||trace.isBlank())trace=UUID.randomUUID().toString();MDC.put("traceId",trace);p.setHeader("X-Trace-Id",trace);try{c.doFilter(r,p);}finally{String pattern=String.valueOf(Optional.ofNullable(r.getAttribute(HandlerMapping.BEST_MATCHING_PATTERN_ATTRIBUTE)).orElse(r.getRequestURI()));String status=String.valueOf(p.getStatus());long nanos=System.nanoTime()-start;metrics.counter("agriconnect.http.requests","service","logistics-service","method",r.getMethod(),"endpoint",pattern,"status",status).increment();metrics.timer("agriconnect.http.duration","service","logistics-service","method",r.getMethod(),"endpoint",pattern).record(nanos,java.util.concurrent.TimeUnit.NANOSECONDS);var a=SecurityContextHolder.getContext().getAuthentication();String user=a==null?"anonymous":String.valueOf(a.getName());log.info("{\"service\":\"logistics-service\",\"traceId\":\"{}\",\"userId\":\"{}\",\"endpoint\":\"{}\",\"status\":{},\"durationMs\":{}}",trace,user,pattern,status,nanos/1_000_000);MDC.remove("traceId");}}}
